    Mockito.verify(socket, Mockito.times(1)).close();
    conn.close();
    Mockito.verify(socket, Mockito.times(1)).close();
    Mockito.verify(outstream, Mockito.times(1)).write(Mockito.<byte[]>any(), Mockito.anyInt(), Mockito.anyInt());
}

