@Test
public void testResponsePrematureTermination() throws Exception {
    final CountDownLatch latch = new CountDownLatch(1);
    final HttpAsyncResponseProducer responseProducer = new HttpAsyncResponseProducer() {

        @Override
        public HttpResponse generateResponse() {
            final HttpResponse response = new BasicHttpResponse(200, "OK");
            final BasicHttpEntity entity = new BasicHttpEntity();
            entity.setContentType(ContentType.DEFAULT_BINARY.toString());
            entity.setChunked(true);
            response.setEntity(entity);
            return response;
        }

        @Override
        public void close() throws IOException {
            latch.countDown();
        }

        @Override
        public void responseCompleted(final HttpContext context) {
        }

        @Override
        public void produceContent(final ContentEncoder encoder, final IOControl ioctrl) throws IOException {
            // suspend output
            ioctrl.suspendOutput();
        }

        @Override
        public void failed(final Exception ex) {
        }
    };
    this.server.registerHandler("*", new HttpAsyncRequestHandler<HttpRequest>() {

        @Override
        public HttpAsyncRequestConsumer<HttpRequest> processRequest(final HttpRequest request, final HttpContext context) throws HttpException, IOException {
            return new BasicAsyncRequestConsumer();
        }

        @Override
        public void handle(final HttpRequest data, final HttpAsyncExchange httpExchange, final HttpContext context) throws HttpException, IOException {
            httpExchange.submitResponse(responseProducer);
        }
    });
    this.server.start();
    final ListenerEndpoint endpoint = this.server.getListenerEndpoint();
    endpoint.waitFor();
    final InetSocketAddress address = (InetSocketAddress) endpoint.getAddress();
    try (final Socket socket = new Socket("localhost", address.getPort())) {
        final OutputStream outstream = socket.getOutputStream();
        final BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(outstream, "US-ASCII"));
        writer.write("GET /long HTTP/1.1\r\n");
        writer.write("Host: localhost\r\n");
        writer.write("\r\n");
        writer.flush();
        Thread.sleep(250);
        writer.close();
    }
    Assert.assertTrue(latch.await(5, TimeUnit.SECONDS));
}

