    h = registry.lookup(new BasicHttpRequest("GET", "/that.form?whatever"), context);
    Assert.assertNotNull(h);
    Assert.assertTrue(h2 == h);
    h = registry.lookup(new BasicHttpRequest("GET", "/whatever"), context);
    Assert.assertNotNull(h);
    Assert.assertTrue(def == h);
}

