            try {
                final OutputStream outputStream = socket.getOutputStream();
                outputStream.write(new byte[] { 'H', 'i' });
                outputStream.flush();
            } finally {
                socket.close();
            }
            return Boolean.TRUE;
        }
    });
    final int localPort = serverSocket.getLocalPort();
